//! Conservative relational-authority ceiling for Wisdom & Care deliberation.

use std::collections::BTreeSet;
use crate::care::{CareCase, CareGap, CareOption, CompetenceAssessment, CompetenceLevel};
use crate::consent::{ConsentEvaluation, ConsentLedger, ConsentPolicy, ConsentScopeId, ConsentState};
use crate::ontology::{ActionAuthority, EpistemicState};
use crate::perspective::PerspectiveGraph;

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AuthorityEnvelopePolicy { pub material_uncertainty_threshold:f32, pub high_relational_dependency_threshold:f32, pub high_vulnerability_threshold:f32, pub min_competence_confidence:f32 }
impl AuthorityEnvelopePolicy { pub fn new(a:f32,b:f32,c:f32,d:f32)->Result<Self,AuthorityEnvelopeError>{ for v in [a,b,c,d]{validate_metric(v)?;} Ok(Self{material_uncertainty_threshold:a,high_relational_dependency_threshold:b,high_vulnerability_threshold:c,min_competence_confidence:d}) } }

#[derive(Debug, Clone, PartialEq)]
pub struct RelationalAuthorityInput { requested:ActionAuthority, epistemic:EpistemicState, consent:ConsentEvaluation, consent_required:bool, provider_competence:CompetenceLevel, provider_competence_confidence:f32, relational_dependency:f32, vulnerability:f32, pre_action_care_gap_count:usize, unresolved_stakeholders:usize, accountable_human_available:bool }
impl RelationalAuthorityInput {
 #[allow(clippy::too_many_arguments)]
 pub fn from_context(requested:ActionAuthority,epistemic:EpistemicState,care_case:&CareCase,option:&CareOption,competence:&CompetenceAssessment,consent_ledger:&ConsentLedger,consent_policy:ConsentPolicy,current_revision:u64,perspectives:&PerspectiveGraph,relational_dependency:f32,vulnerability:f32,accountable_human_available:bool)->Result<Self,AuthorityEnvelopeError>{
  validate_metric(relational_dependency)?;validate_metric(vulnerability)?;
  if competence.provider!=option.provider{return Err(AuthorityEnvelopeError::ProviderMismatch);} if requested==ActionAuthority::ActReversible&&!option.reversible{return Err(AuthorityEnvelopeError::IrreversibleOptionMisclassified);}
  let scope=ConsentScopeId::new(option.id.as_str()).map_err(|_|AuthorityEnvelopeError::InvalidConsentScope)?; let consent=consent_ledger.evaluate(&care_case.stakeholder,&scope,current_revision,consent_policy);
  let pre_action_care_gap_count=care_case.gaps().iter().filter(|g|!matches!(g,CareGap::MissingPersonResponse(_)|CareGap::MissingOutcome(_))).count(); let summary=perspectives.coverage_summary(); let mut unresolved_stakeholders=summary.unresolved;
  match perspectives.find(&care_case.stakeholder){None=>unresolved_stakeholders=unresolved_stakeholders.saturating_add(1),Some(p) if !p.affected=>unresolved_stakeholders=unresolved_stakeholders.saturating_add(1),Some(_)=>{}}
  Self::new_unchecked_context(requested,epistemic,consent,option.requires_consent,competence.level,competence.confidence,relational_dependency,vulnerability,pre_action_care_gap_count,unresolved_stakeholders,accountable_human_available)
 }
 #[allow(clippy::too_many_arguments)] fn new_unchecked_context(requested:ActionAuthority,epistemic:EpistemicState,consent:ConsentEvaluation,consent_required:bool,provider_competence:CompetenceLevel,provider_competence_confidence:f32,relational_dependency:f32,vulnerability:f32,pre_action_care_gap_count:usize,unresolved_stakeholders:usize,accountable_human_available:bool)->Result<Self,AuthorityEnvelopeError>{validate_metric(provider_competence_confidence)?;validate_metric(relational_dependency)?;validate_metric(vulnerability)?;Ok(Self{requested,epistemic,consent,consent_required,provider_competence,provider_competence_confidence,relational_dependency,vulnerability,pre_action_care_gap_count,unresolved_stakeholders,accountable_human_available})}
}

#[derive(Debug,Clone,PartialEq,Eq,PartialOrd,Ord)] pub enum AuthorityRestrictionReason{ConsentNotEffective,ConsentRefusedOrWithdrawn,ProviderCompetenceUnknownOrInsufficient,ProviderCompetenceConfidenceInsufficient,ProviderCompetenceBoundedForIrreversibleAction,CareProcessIncomplete,UnresolvedStakeholders,MaterialFactualUncertainty,MaterialNormativeUncertainty,HighRelationalDependency,HighVulnerability,IrreversibleActionUnderMaterialUncertainty,HumanReviewRecommended}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct RelationalAuthorityAssessment{requested:ActionAuthority,ceiling:ActionAuthority,reasons:BTreeSet<AuthorityRestrictionReason>,human_review_recommended:bool}
impl RelationalAuthorityAssessment{pub fn requested(&self)->ActionAuthority{self.requested} pub fn ceiling(&self)->ActionAuthority{self.ceiling} pub fn reasons(&self)->&BTreeSet<AuthorityRestrictionReason>{&self.reasons} pub fn human_review_recommended(&self)->bool{self.human_review_recommended} pub fn was_restricted(&self)->bool{self.ceiling<self.requested} #[cfg(test)] pub(crate) fn for_test(requested:ActionAuthority,ceiling:ActionAuthority,reasons:BTreeSet<AuthorityRestrictionReason>,human_review_recommended:bool)->Self{Self{requested,ceiling,reasons,human_review_recommended}}}
#[derive(Debug,Clone,Copy,Default)] pub struct RelationalAuthorityEnvelope;
impl RelationalAuthorityEnvelope{pub fn assess(&self,input:&RelationalAuthorityInput,policy:AuthorityEnvelopePolicy)->RelationalAuthorityAssessment{let mut ceiling=input.requested;let mut reasons=BTreeSet::new();let mut human=false;if matches!(input.consent.state,ConsentState::Refused|ConsentState::Withdrawn){cap(&mut ceiling,ActionAuthority::Advise);reasons.insert(AuthorityRestrictionReason::ConsentRefusedOrWithdrawn);human=true;}else if input.consent_required&&input.requested.is_action_class()&&!input.consent.is_effective(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::ConsentNotEffective);}if input.provider_competence_confidence<policy.min_competence_confidence{cap(&mut ceiling,ActionAuthority::Advise);reasons.insert(AuthorityRestrictionReason::ProviderCompetenceConfidenceInsufficient);}match input.provider_competence{CompetenceLevel::Unknown|CompetenceLevel::Insufficient=>{cap(&mut ceiling,ActionAuthority::Advise);reasons.insert(AuthorityRestrictionReason::ProviderCompetenceUnknownOrInsufficient);}CompetenceLevel::Bounded if input.requested==ActionAuthority::ActIrreversible=>{cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::ProviderCompetenceBoundedForIrreversibleAction);} _=>{}}if input.pre_action_care_gap_count>0&&input.requested.is_action_class(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::CareProcessIncomplete);}if input.unresolved_stakeholders>0&&input.requested.is_action_class(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::UnresolvedStakeholders);human=true;}let factual=input.epistemic.factual_uncertainty>=policy.material_uncertainty_threshold;let normative=input.epistemic.normative_uncertainty>=policy.material_uncertainty_threshold;if factual&&input.requested.is_action_class(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::MaterialFactualUncertainty);}if normative&&input.requested.is_action_class(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::MaterialNormativeUncertainty);human=true;}let relational=input.relational_dependency>=policy.high_relational_dependency_threshold;let vulnerable=input.vulnerability>=policy.high_vulnerability_threshold;if relational&&input.requested.is_action_class(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::HighRelationalDependency);human=true;}if vulnerable&&input.requested.is_action_class(){cap(&mut ceiling,ActionAuthority::Recommend);reasons.insert(AuthorityRestrictionReason::HighVulnerability);human=true;}if input.requested==ActionAuthority::ActIrreversible&&(factual||normative){cap(&mut ceiling,ActionAuthority::Advise);reasons.insert(AuthorityRestrictionReason::IrreversibleActionUnderMaterialUncertainty);human=true;}if input.accountable_human_available&&(relational||vulnerable||input.unresolved_stakeholders>0||normative||input.requested==ActionAuthority::ActIrreversible){reasons.insert(AuthorityRestrictionReason::HumanReviewRecommended);human=true;}RelationalAuthorityAssessment{requested:input.requested,ceiling,reasons,human_review_recommended:human}}}
fn cap(c:&mut ActionAuthority,m:ActionAuthority){if *c>m{*c=m;}} fn validate_metric(v:f32)->Result<(),AuthorityEnvelopeError>{if v.is_finite()&&(0.0..=1.0).contains(&v){Ok(())}else{Err(AuthorityEnvelopeError::InvalidMetric(v))}}
#[derive(Debug,Clone,PartialEq)] pub enum AuthorityEnvelopeError{InvalidMetric(f32),InvalidConsentScope,ProviderMismatch,IrreversibleOptionMisclassified}

#[cfg(test)] mod tests{use super::*;use crate::care::{CareCaseId,CareOptionId,CareProviderCandidate,NeedHypothesisId};use crate::consent::{ConsentInvalidityReason,ConsentValidity};use crate::perspective::{PerspectiveCoverage,StakeholderId,StakeholderPerspective};fn policy()->AuthorityEnvelopePolicy{AuthorityEnvelopePolicy::new(0.5,0.6,0.6,0.5).unwrap()}fn effective()->ConsentEvaluation{ConsentEvaluation{state:ConsentState::Affirmed,validity:ConsentValidity::Effective,reasons:BTreeSet::new()}}fn base(r:ActionAuthority)->RelationalAuthorityInput{RelationalAuthorityInput::new_unchecked_context(r,EpistemicState::new(0.1,0.1),effective(),false,CompetenceLevel::Qualified,1.0,0.1,0.1,0,0,false).unwrap()}#[test]fn monotone(){let low=RelationalAuthorityEnvelope.assess(&base(ActionAuthority::ActIrreversible),policy());let mut h=base(ActionAuthority::ActIrreversible);h.vulnerability=0.9;h.epistemic=EpistemicState::new(0.9,0.9);assert!(RelationalAuthorityEnvelope.assess(&h,policy()).ceiling()<=low.ceiling());}#[test]fn missing_consent_when_required_caps(){let mut i=base(ActionAuthority::ActReversible);i.consent=ConsentEvaluation{state:ConsentState::Unknown,validity:ConsentValidity::NotEffective,reasons:[ConsentInvalidityReason::NoRecordForScope].into_iter().collect()};i.consent_required=true;assert_eq!(RelationalAuthorityEnvelope.assess(&i,policy()).ceiling(),ActionAuthority::Recommend);}#[test]fn context_binds(){let s=StakeholderId::new("p").unwrap();let care=CareCase::new(CareCaseId::new("c").unwrap(),s.clone());let o=CareOption::new(CareOptionId::new("o").unwrap(),NeedHypothesisId::new("n").unwrap(),CareProviderCandidate::Symthaea,"x",[],[],true,true).unwrap();let comp=CompetenceAssessment::new(CareProviderCandidate::Symthaea,CompetenceLevel::Qualified,0.9,vec![]).unwrap();let l=ConsentLedger::new();let p=PerspectiveGraph::try_new(vec![StakeholderPerspective::new(s,true,PerspectiveCoverage::Unknown)]).unwrap();let i=RelationalAuthorityInput::from_context(ActionAuthority::ActReversible,EpistemicState::new(0.1,0.1),&care,&o,&comp,&l,ConsentPolicy::new(0.2,false).unwrap(),1,&p,0.1,0.1,false).unwrap();assert!(i.pre_action_care_gap_count>0);}}
